statement-execution-processor.statement:
DECLARE
    v_prompt   CLOB;
    v_response CLOB;
BEGIN
WITH ranked AS (
    SELECT CONTENT
        FROM REPORTS_NO_WEEK rnw
        ORDER BY vector_distance(
                    rnw.EMBEDDING_TITLE,
                    vector_embedding(doc_model
                            USING {#0} AS data)
        ) ASC
    FETCH FIRST 5 ROWS ONLY
), prompt_text AS (
        SELECT LISTAGG(CONTENT, CHR(10))
        WITHIN GROUP (ORDER BY NULL) AS prompt
        FROM ranked
        )
SELECT prompt
        INTO v_prompt
        FROM prompt_text;

v_response := DBMS_VECTOR.UTL_TO_GENERATE_TEXT(
v_prompt,
    JSON({#1})
);

? := v_response;
END;

BEGIN
    DBMS_VECTOR.LOAD_ONNX_MODEL_CLOUD(
        model_name => {#0},
        credential => {#1},
        uri        => {#2});
END;

DECLARE
table_already_exists EXCEPTION;
PRAGMA EXCEPTION_INIT(table_already_exists, -955);
BEGIN
    EXECUTE IMMEDIATE '
            CREATE TABLE {0}.{1} (
            id VARCHAR2(50) NOT NULL PRIMARY KEY,
            file_content BLOB,
            metadata JSON,
            file_hash VARCHAR2(32) NOT NULL,
            file_size NUMBER(19) NOT NULL,
            CONSTRAINT uk_file_identity UNIQUE (file_hash, file_size)
            ) LOB(file_content) STORE AS SECUREFILE (NOCACHE FILESYSTEM_LIKE_LOGGING)
            ';

    RAISE_APPLICATION_ERROR(-20001, 'TABLE_CREATED');

    EXCEPTION
    WHEN table_already_exists THEN
        RAISE_APPLICATION_ERROR(-20002, 'TABLE_EXISTS');
END;

INSERT INTO {0}
(id, file_content, metadata,file_hash,file_size)
VALUES ({#1}, EMPTY_BLOB(), {#2},{#3},{#4})

select
    CHUNK_OFFSET as "Chunk offset",
    CHUNK_LENGTH as "Chunk length",
    CHUNK_TEXT as "Chunk text"
from VECTOR_CHUNKS(
    {#0}
    BY {1}
    MAX {2}
    OVERLAP {3}
    SPLIT BY {4})
